import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals["Sheet1"]
dws = vals["Data"]
ows = wb["Sheet1"]

def norm_key(x):
    if isinstance(x, bool):
        return x
    if isinstance(x, (int, float)):
        f = float(x)
        return int(f) if f.is_integer() else f
    s = str(x).strip()
    try:
        f = float(s)
        return int(f) if f.is_integer() else f
    except Exception:
        return s

def norm_val(x):
    if isinstance(x, bool):
        return x
    if isinstance(x, (int, float)):
        f = float(x)
        return int(f) if f.is_integer() else f
    s = str(x).strip()
    try:
        f = float(s)
        return int(f) if f.is_integer() else f
    except Exception:
        return s

header_row = 2
lookup = {}

for r in range(3, dws.max_row + 1):
    job = dws.cell(r, 2).value
    if job is None:
        continue

    job_key = str(job).strip()
    months = {}

    for c in range(3, dws.max_column + 1):
        month_header = dws.cell(header_row, c).value
        value = dws.cell(r, c).value

        if month_header is None or value is None:
            continue

        months[norm_key(month_header)] = value

    lookup[job_key] = months

for r in range(2, vws.max_row + 1):
    job = vws.cell(r, 1).value
    month = vws.cell(r, 2).value

    if job is None and month is None:
        continue

    job_key = str(job).strip() if job is not None else None
    month_key = norm_key(month) if month is not None else None

    result = None
    if job_key is not None and month_key is not None and job_key in lookup:
        result = lookup[job_key].get(month_key)

    ows.cell(r, 3).value = norm_val(result) if result is not None else None
    print(r, job_key, month_key, ows.cell(r, 3).value)

wb.save(OUT)
